using System;
using UnityEngine;
using UnityEngine.Localization.SmartFormat;

namespace Astrea;

[CreateAssetMenu(fileName = "EndOfTurnGainSomethingPerDiceOmen", menuName = "Data/Battle/Omens System/Omen Data/Any/EndOfTurnGainSomethingPerDiceOmen")]
public class EndOfTurnGainSomethingPerDiceOmen : OmenData
{
	protected Action omenAction;

	protected Action omenCheckActivationAction;

	public override void Initialize(OmenInstance omenInstance)
	{
		omenAction = delegate
		{
			omenInstance.EnqueueOmenFeedbackAndPlay();
			int diceInHandAmount = ReferenceSingleton<PlayerDiceHandHolder>.Instance.GetDiceInHandAmount();
			OmenLogic.ActivateOmen(BattleAction, ActionValue * diceInHandAmount, null, null, (this is PerpetualClockOmenData) ? CorruptionPurifyModifierEnum.CANTBEINCREASEDCORRUPTION : CorruptionPurifyModifierEnum.NONE);
		};
		omenCheckActivationAction = delegate
		{
			if (ReferenceSingleton<PlayerDiceHandHolder>.Instance.GetDiceInHandAmount() != 0)
			{
				if (this is PerpetualClockOmenData)
				{
					ReferenceSingleton<StartBattleStartEndTurnOmensHandler>.Instance.PerpetualClockReceiveCorruptionOmenAction = omenAction;
				}
				else
				{
					ReferenceSingleton<StartBattleStartEndTurnOmensHandler>.Instance.EndOfTurnOmenActions.Add(omenAction);
				}
			}
		};
		ReferenceSingleton<StartBattleStartEndTurnOmensHandler>.Instance.EndOfTurnOmenCheckActivateActions.Add(omenCheckActivationAction);
	}

	public override void OmenRemoved()
	{
		ReferenceSingleton<StartBattleStartEndTurnOmensHandler>.Instance.EndOfTurnOmenCheckActivateActions.Remove(omenCheckActivationAction);
	}

	public override string OmenConvertedDescription()
	{
		return Smart.Format(base.localizationManager.GetLocalizedEndTurnRemainDiceChantText(), base.localizationManager.GetLocalizedAtTheEndOfYourTurn(), base.OmenConvertedDescription().RemoveLastIfNotJapaneseNorKoreanNorTraditionalChinese());
	}
}
